'use strict';

// MODULES //

var numelDimension = require( '@stdlib/ndarray/base/numel-dimension' );
var getStride = require( '@stdlib/ndarray/base/stride' );
var getOffset = require( '@stdlib/ndarray/base/offset' );
var getData = require( '@stdlib/ndarray/base/data-buffer' );
var ndarraylike2scalar = require( '@stdlib/ndarray/base/ndarraylike2scalar' );
var cwax = require( '@stdlib/blas/ext/base/cwax' ).ndarray;
var capx = require( '@stdlib/blas/ext/base/capx' ).ndarray;


// MAIN //

/**
* Multiplies each element in an input one-dimensional single-precision complex floating-point ndarray by a scalar constant and adds a scalar constant before assigning the results to elements in a one-dimensional single-precision complex floating-point output ndarray.
*
* ## Notes
*
* -   The function expects the following ndarrays:
*
*     -   a one-dimensional input ndarray.
*     -   a one-dimensional output ndarray.
*     -   a zero-dimensional ndarray containing the scalar constant to multiply.
*     -   a zero-dimensional ndarray containing the scalar constant to add.
*
* @param {ArrayLikeObject<Object>} arrays - array-like object containing ndarrays
* @returns {ndarray} output ndarray
*
* @example
* var Complex64Vector = require( '@stdlib/ndarray/vector/complex64' );
* var Complex64 = require( '@stdlib/complex/float32/ctor' );
* var scalar2ndarray = require( '@stdlib/ndarray/from-scalar' );
*
* var x = new Complex64Vector( [ -2.0, 1.0, 3.0, -5.0 ] );
* var w = new Complex64Vector( 2 );
*
* var alpha = scalar2ndarray( new Complex64( 5.0, 0.0 ), {
*     'dtype': 'complex64'
* });
*
* var beta = scalar2ndarray( new Complex64( 3.0, 0.0 ), {
*     'dtype': 'complex64'
* });
*
* var out = cwaxpb( [ x, w, alpha, beta ] );
* // returns <ndarray>[ <Complex64>[ -7.0, 5.0 ], <Complex64>[ 18.0, -25.0 ] ]
*
* var bool = ( out === w );
* // returns true
*/
function cwaxpb( arrays ) {
	var alpha;
	var wbuf;
	var beta;
	var sw;
	var ow;
	var N;
	var x;
	var w;

	x = arrays[ 0 ];
	w = arrays[ 1 ];
	alpha = ndarraylike2scalar( arrays[ 2 ] );
	beta = ndarraylike2scalar( arrays[ 3 ] );

	N = numelDimension( x, 0 );
	wbuf = getData( w );
	sw = getStride( w, 0 );
	ow = getOffset( w );

	// Multiply each element by the scalar constant (w = alpha*x):
	cwax( N, alpha, getData( x ), getStride( x, 0 ), getOffset( x ), wbuf, sw, ow ); // eslint-disable-line max-len

	// Add the scalar constant (w += beta):
	capx( N, beta, wbuf, sw, ow );

	return w;
}


// EXPORTS //

module.exports = cwaxpb;
